examples.good:
var wg sync.WaitGroup
for _, item := range items {
	wg.Go(func() {
		process(item)
	})
}
wg.Wait()

examples.bad:
for _, item := range items {
	go process(item)
}

examples.good:
ch := make(chan int)
go func() {
	defer close(ch)
	for _, v := range vals {
		ch <- v
	}
}()

examples.bad:
ch := make(chan int)
go func() {
	for _, v := range vals {
		ch <- v
	}
}()
<-ch
close(ch)

