examples.good:
type counter struct {
	mu sync.Mutex
	n  int
}

func (c *counter) inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n++
}

examples.bad:
type counter struct {
	mu sync.Mutex
	N  int // exported field, callers can bypass the lock and mutate it directly
}

examples.good:
if err := save(); err != nil {
	return err
}
process()

examples.bad:
if err := save(); err == nil {
	process()
} else {
	return err
}

examples.good:
fns := make([]func(), 0, len(items))
for _, item := range items {
	fns = append(fns, func() {
		process(item)
	})
}

